//! The Grafana dashboard (MET-19, MET-22): `ops/grafana/dashboards/towercab.json`, generated by
//! `ops/grafana/build_dashboard.py`, its queries checked against the emitter's one name list
//! (MET-13). Was `tests/test_ops.py`'s `DashboardTest`.

mod common;

use std::process::Command;

use regex::Regex;
use serde_json::Value;
use towercab::metrics::METRICS;

const DASHBOARD: &str = "ops/grafana/dashboards/towercab.json";

fn dashboard() -> Value {
    serde_json::from_str(&common::read(DASHBOARD)).expect("the dashboard is JSON")
}

fn panels(d: &Value) -> &Vec<Value> {
    d["panels"].as_array().expect("panels")
}

/// (panel title, target) of every query.
fn targets(d: &Value) -> Vec<(String, Value)> {
    panels(d)
        .iter()
        .flat_map(|p| {
            let title = p["title"].as_str().unwrap_or_default().to_string();
            p["targets"]
                .as_array()
                .cloned()
                .unwrap_or_default()
                .into_iter()
                .map(move |t| (title.clone(), t))
        })
        .collect()
}

fn expr(t: &Value) -> &str {
    t["expr"].as_str().expect("expr")
}

#[test]
fn test_refresh_picker_and_overall_only() {
    let d = dashboard();
    assert_eq!(d["uid"], "towercab-overview");
    let intervals: Vec<&str> = d["timepicker"]["refresh_intervals"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap())
        .collect();
    assert_eq!(intervals.first(), Some(&"10s"));
    assert_eq!(intervals.last(), Some(&"1d"));
    assert!(intervals.contains(&"1m"));
    assert_eq!(d["refresh"], "1m");
    let names: Vec<&str> = d["templating"]["list"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v["name"].as_str().unwrap())
        .collect();
    assert!(!names.contains(&"repo"), "{names:?}");
    for (title, t) in targets(&d) {
        assert!(!expr(&t).contains("$repo"), "{title}");
    }
}

#[test]
fn test_panels_well_formed() {
    let d = dashboard();
    let mut ids: Vec<i64> = panels(&d)
        .iter()
        .map(|p| p["id"].as_i64().unwrap())
        .collect();
    let n = ids.len();
    ids.sort();
    ids.dedup();
    assert_eq!(ids.len(), n, "panel ids unique");
    for p in panels(&d) {
        let g = &p["gridPos"];
        let title = p["title"].as_str().unwrap();
        assert!(
            g["x"].as_i64().unwrap() + g["w"].as_i64().unwrap() <= 24,
            "{title}"
        );
    }
    for (title, t) in targets(&d) {
        let uid = t["datasource"]["uid"].as_str().unwrap();
        assert!(["prometheus", "loki"].contains(&uid), "{title}");
        let e = expr(&t);
        assert_eq!(e.matches('(').count(), e.matches(')').count(), "{title}");
    }
}

#[test]
fn test_dashboard_names() {
    // OTel names as Prometheus spells them (`.` → `_`); suffixes (`_total`, `_seconds`,
    // `_bucket`, …) after a known name are fine. Longest first, so a prefix can't shadow.
    let mut bases: Vec<String> = METRICS.iter().map(|m| m.name().replace('.', "_")).collect();
    bases.sort_by_key(|b| std::cmp::Reverse(b.len()));
    let name = Regex::new(r"towercab_[a-z_]+").unwrap();
    let mut seen = 0;
    for (title, t) in targets(&dashboard()) {
        let e = expr(&t);
        for m in name.find_iter(e) {
            let n = m.as_str();
            assert!(
                bases
                    .iter()
                    .any(|b| n == b || n.starts_with(&format!("{b}_"))),
                "{title}: {n} isn't in metrics::METRICS"
            );
            seen += 1;
        }
        assert!(!e.contains("gen_ai_"), "{title}");
    }
    assert!(seen > 40, "the dashboard queries the loop's metrics");
}

#[test]
fn test_dashboard_is_generated() {
    let tmp = tempfile::tempdir().unwrap();
    let out = tmp.path().join("towercab.json");
    let run = Command::new("python3")
        .arg(common::root().join("ops/grafana/build_dashboard.py"))
        .arg(&out)
        .output()
        .expect("python3 runs");
    assert!(
        run.status.success(),
        "{}",
        String::from_utf8_lossy(&run.stderr)
    );
    assert_eq!(
        std::fs::read_to_string(&out).unwrap(),
        common::read(DASHBOARD),
        "regenerate: python3 ops/grafana/build_dashboard.py {DASHBOARD}"
    );
}

#[test]
fn test_delta_counters_summed_not_increased() {
    let f = Regex::new(r"(^|[^\w])(increase|rate|irate)\(").unwrap();
    for (title, t) in targets(&dashboard()) {
        assert!(!f.is_match(expr(&t)), "{title}: {}", expr(&t));
    }
}
